Object.assign(window.POC_SRC,{"roll-log": "\"\"\"\nRoll Transparency Log - proof of concept (pure Python, standard library only).\n\nEvery change to an electoral roll (add / delete / correct) is appended to an\nappend-only Merkle log in the style of Certificate Transparency (RFC 6962 /\nRFC 9162 hashing: leaf = H(0x00 || entry), node = H(0x01 || left || right)).\n\nFour labs:\n  1. scale     - append 1,000,000 changes; how big is a voter's inclusion proof, how fast to check?\n  2. inclusion - a voter (Priya) looks up her own entry with a private lookup key and verifies the proof\n  3. rewrite   - an insider silently changes one old entry; monitors compare consistency proofs and catch it\n  4. privacy   - what an outsider can learn from the public log (pseudonymous ids, coarse codes), and what not\n\nHONESTY: the roll, the voters and the changes are SYNTHETIC (seeded). The\nhashing, proofs and verification are real. Signatures of tree heads are modelled\nwith HMAC (a real system uses Ed25519). The same file runs natively and in Pyodide.\n\"\"\"\nimport hashlib, hmac, random, time, json\n\nH = lambda b: hashlib.sha256(b).digest()\nREASONS = [\"R-DEAD\", \"R-DUP\", \"R-SHIFT\", \"R-ABSENT\", \"R-NOFORM\", \"R-REQ\", \"R-COURT\", \"A-NEW\", \"A-RESTORE\", \"M-MOVE\", \"M-FIX\"]   # the 11 codes of the spec; no \"other\"\nLOG_KEY = b\"demo-log-signing-key\"            # stands in for the log's signing key\nSALT = b\"demo-per-state-pepper\"             # pepper held by the Election Commission HSM in the real design\n\ndef leaf_hash(entry: bytes) -> bytes: return H(b\"\\x00\" + entry)\ndef node_hash(l: bytes, r: bytes) -> bytes: return H(b\"\\x01\" + l + r)\n\ndef voter_tag(epic: str) -> str:\n    \"\"\"Pseudonymous, stable id for a voter: HMAC(pepper, EPIC). Public on the log; not reversible without the pepper.\"\"\"\n    return hmac.new(SALT, epic.encode(), hashlib.sha256).hexdigest()[:20]\n\nclass Log:\n    def __init__(self): self.levels = [[]]   # levels[0] = leaf hashes\n    def append(self, entry: bytes):\n        h = leaf_hash(entry); self.levels[0].append(h); i = len(self.levels[0]) - 1; lv = 0\n        while i % 2 == 1:                      # incremental: complete subtrees only\n            if len(self.levels) <= lv + 1: self.levels.append([])\n            self.levels[lv + 1].append(node_hash(self.levels[lv][i - 1], self.levels[lv][i])); i //= 2; lv += 1\n    @property\n    def size(self): return len(self.levels[0])\n    def _mth(self, lo, hi):                     # Merkle tree hash of leaves [lo, hi), RFC 6962 §2.1\n        n = hi - lo\n        if n == 1: return self.levels[0][lo]\n        k = 1 << ((n - 1).bit_length() - 1)\n        lv = k.bit_length() - 1\n        if lo % k == 0 and len(self.levels) > lv and lo // k < len(self.levels[lv]) and k == (1 << lv):\n            left = self.levels[lv][lo // k]\n        else: left = self._mth(lo, lo + k)\n        return node_hash(left, self._mth(lo + k, hi))\n    def root(self, size=None): return self._mth(0, size or self.size)\n    def inclusion(self, m, n=None):            # audit path for leaf m in tree of size n\n        n = n or self.size; path = []\n        def rec(m, lo, hi):\n            if hi - lo == 1: return\n            k = 1 << ((hi - lo - 1).bit_length() - 1)\n            if m < lo + k: rec(m, lo, lo + k); path.append(self._mth(lo + k, hi))\n            else: rec(m, lo + k, hi); path.append(self._mth(lo, lo + k))\n        rec(m, 0, n); return path\n    def consistency(self, m, n=None):          # RFC 6962 §2.1.2 SUBPROOF\n        n = n or self.size\n        def sub(m, lo, hi, b):\n            size = hi - lo\n            if m == size: return [] if b else [self._mth(lo, hi)]\n            k = 1 << ((size - 1).bit_length() - 1)\n            if m <= k: return sub(m, lo, lo + k, b) + [self._mth(lo + k, hi)]\n            return sub(m - k, lo + k, hi, False) + [self._mth(lo, lo + k)]\n        return sub(m, 0, n, True)\n\ndef verify_inclusion(leaf: bytes, m: int, n: int, path, root) -> bool:   # RFC 9162 §2.1.3.2\n    if m >= n: return False\n    fn, sn, r = m, n - 1, leaf\n    for p in path:\n        if sn == 0: return False\n        if fn % 2 == 1 or fn == sn:\n            r = node_hash(p, r)\n            if fn % 2 == 0:\n                while fn % 2 == 0 and fn != 0: fn >>= 1; sn >>= 1\n        else: r = node_hash(r, p)\n        fn >>= 1; sn >>= 1\n    return sn == 0 and r == root\n\ndef verify_consistency(m, n, proof, old_root, new_root) -> bool:        # RFC 9162 §2.1.4.2\n    if m == n: return old_root == new_root and not proof\n    if m == 0 or m > n: return False\n    if m & (m - 1) == 0: proof = [old_root] + proof\n    fn, sn = m - 1, n - 1\n    while fn % 2 == 1: fn >>= 1; sn >>= 1\n    fr = sr = proof[0]\n    for c in proof[1:]:\n        if sn == 0: return False\n        if fn % 2 == 1 or fn == sn:\n            fr = node_hash(c, fr); sr = node_hash(c, sr)\n            if fn % 2 == 0:\n                while fn % 2 == 0 and fn != 0: fn >>= 1; sn >>= 1\n        else: sr = node_hash(sr, c)\n        fn >>= 1; sn >>= 1\n    return sn == 0 and fr == old_root and sr == new_root\n\ndef sth(log):            # signed tree head\n    r = log.root(); sig = hmac.new(LOG_KEY, log.size.to_bytes(8, \"big\") + r, hashlib.sha256).hexdigest()[:16]\n    return {\"size\": log.size, \"root\": r.hex()[:16], \"sig\": sig, \"_root\": r}\n\ndef entry(seq, tag, reason, booth, date, officer):\n    return json.dumps({\"seq\": seq, \"voter\": tag, \"op\": reason[0], \"reason\": reason, \"booth\": booth, \"date\": date, \"officer\": officer}, separators=(\",\", \":\")).encode()\n\ndef synth(n, seed=3, priya_at=None):\n    rng = random.Random(seed); out = []\n    for i in range(n):\n        reason = rng.choices(REASONS, weights=[8, 6, 14, 9, 4, 3, 1, 30, 5, 10, 10])[0]\n        epic = \"UP\" + str(rng.randrange(10**9)).zfill(9)\n        booth, date, officer = \"AC-%03d/B-%03d\" % (rng.randrange(400), rng.randrange(300)), \"2025-%02d-%02d\" % (rng.randint(8, 11), rng.randint(1, 28)), \"ero-\" + hashlib.sha1(str(rng.randrange(900)).encode()).hexdigest()[:4]\n        if priya_at is not None and i == priya_at: epic, reason, date, officer = \"UPGND0412873\", \"R-SHIFT\", \"2025-11-14\", \"ero-7f3a\"   # Priya (fictional), as in the story\n        out.append(entry(i, voter_tag(epic), reason, booth, date, officer))\n    return out\n\ndef lab_scale(n=1_000_000):\n    log = Log(); t0 = time.time()\n    for e in synth(n, seed=5): log.append(e)\n    t1 = time.time(); head = sth(log)\n    rng = random.Random(9); sizes = []; tv = 0\n    for _ in range(200):\n        m = rng.randrange(n); p = log.inclusion(m); sizes.append(len(p))\n        a = time.time(); assert verify_inclusion(log.levels[0][m], m, n, p, head[\"_root\"]); tv += time.time() - a\n    return {\"entries\": n, \"append_s\": round(t1 - t0, 2), \"proof_hashes\": max(sizes), \"proof_bytes\": max(sizes) * 32,\n            \"verify_ms\": round(tv / 200 * 1000, 3), \"root\": head[\"root\"], \"projection_130M_hashes\": (130_000_000 - 1).bit_length()}\n\ndef lab_inclusion(n=50_000):\n    es = synth(n, seed=7, priya_at=31_337); log = Log()\n    for e in es: log.append(e)\n    head = sth(log); my = voter_tag(\"UPGND0412873\")\n    hits = [i for i, e in enumerate(es) if json.loads(e)[\"voter\"] == my]\n    i = hits[0]; p = log.inclusion(i); ok = verify_inclusion(leaf_hash(es[i]), i, n, p, head[\"_root\"])\n    forged = json.loads(es[i]); forged[\"reason\"] = \"R-DEAD\"; bad = json.dumps(forged, separators=(\",\", \":\")).encode()\n    ok_forged = verify_inclusion(leaf_hash(bad), i, n, p, head[\"_root\"])\n    return {\"size\": n, \"found_at\": i, \"entry\": json.loads(es[i]), \"proof_len\": len(p), \"verified\": ok, \"forged_reason_verifies\": ok_forged, \"sth\": {k: v for k, v in head.items() if k != \"_root\"}}\n\ndef lab_rewrite(n=20_000, m=12_000):\n    es = synth(n, seed=11); log = Log()\n    for e in es[:m]: log.append(e)\n    old = sth(log)\n    for e in es[m:]: log.append(e)\n    new = sth(log); honest = verify_consistency(m, n, log.consistency(m), old[\"_root\"], new[\"_root\"])\n    # insider rewrites entry 4242 (a deletion's reason) and rebuilds the tree\n    t = json.loads(es[4242]); t[\"reason\"] = \"R-DEAD\"; es2 = list(es); es2[4242] = json.dumps(t, separators=(\",\", \":\")).encode()\n    log2 = Log()\n    for e in es2: log2.append(e)\n    new2 = sth(log2); caught = not verify_consistency(m, n, log2.consistency(m), old[\"_root\"], new2[\"_root\"])\n    return {\"old_size\": m, \"new_size\": n, \"honest_consistent\": honest, \"tampered_entry\": 4242, \"rewrite_caught\": caught, \"proof_len\": len(log.consistency(m)),\n            \"old_root\": old[\"root\"], \"honest_root\": new[\"root\"], \"tampered_root\": new2[\"root\"]}\n\ndef lab_privacy(n=50_000):\n    es = [json.loads(e) for e in synth(n, seed=13)]\n    by_reason = {}\n    for e in es: by_reason[e[\"reason\"]] = by_reason.get(e[\"reason\"], 0) + 1\n    booths = {}\n    for e in es: booths[e[\"booth\"]] = booths.get(e[\"booth\"], 0) + 1\n    small = sum(1 for v in booths.values() if v < 5)\n    guess = voter_tag(\"UP000000001\") in {e[\"voter\"] for e in es}\n    return {\"by_reason\": by_reason, \"booths\": len(booths), \"booths_under_5\": small, \"tag_reversible_without_pepper\": False,\n            \"random_epic_found\": guess, \"fields_public\": [\"voter tag (pseudonym)\", \"reason code\", \"booth\", \"date\", \"officer pseudonym\"],\n            \"fields_never\": [\"name\", \"EPIC number\", \"address\", \"religion\", \"caste\", \"photo\"]}\n\ndef run_all(big=True):\n    return {\"scale\": lab_scale(1_000_000 if big else 100_000), \"inclusion\": lab_inclusion(), \"rewrite\": lab_rewrite(), \"privacy\": lab_privacy()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: scale | inclusion | rewrite | privacy. Browser-sized runs; the full million was run natively.\"\"\"\n    ev, ck = [], []\n    if sc == \"scale\":\n        n = 20_000; t0 = time.time(); log = Log()\n        for e in synth(n, seed=5): log.append(e)\n        dt = time.time() - t0; head = sth(log); p = log.inclusion(777)\n        a = time.time(); ok = verify_inclusion(log.levels[0][777], 777, n, p, head[\"_root\"]); tv = (time.time() - a) * 1000\n        ev += [_ev(\"O\", \"L\", \"batch\", f\"{n:,} synthetic changes appended in {dt:.2f}s\", f\"{n:,} שורות\"),\n               _ev(\"L\", \"L\", \"head\", f\"signed tree head: size={n} root={head['root']} sig={head['sig']}\", \"ראש חתום\"),\n               _ev(\"L\", \"V\", \"proof\", f\"inclusion proof for entry 777: {len(p)} hashes = {len(p)*32} bytes\", f\"{len(p)} גיבובים\", ok=True),\n               _ev(\"V\", \"V\", \"verify\", f\"verified on the 'phone' in {tv:.3f} ms -> {ok}\", \"אומת\", ok=ok),\n               _ev(\"L\", \"L\", \"project\", f\"130,000,000 entries -> {(130_000_000-1).bit_length()} hashes per proof (native run: 1,000,000 in 18.8s, 20 hashes)\", \"27 ב-130M\", ok=True)]\n        ck += [[\"proof_short\", len(p) <= 32], [\"verify_fast\", tv < 50 and ok]]\n    elif sc == \"inclusion\":\n        r = lab_inclusion(50_000)\n        ev += [_ev(\"O\", \"P\", \"pseudonym\", \"Priya's elector ID -> HMAC pseudonym (no name, no ID on the log)\", \"כינוי\"),\n               _ev(\"P\", \"L\", \"entry\", f\"entry #{r['found_at']:,}: {r['entry']['reason']} booth {r['entry']['booth']} {r['entry']['date']}\", \"שורה\"),\n               _ev(\"L\", \"V\", \"proof\", f\"inclusion proof: {r['proof_len']} hashes against head {r['sth']['root']}\", f\"{r['proof_len']} גיבובים\"),\n               _ev(\"V\", \"V\", \"verify\", f\"Priya's phone rebuilds the head -> {r['verified']}\", \"אומת\", ok=r[\"verified\"]),\n               _ev(\"V\", \"V\", \"forged\", f\"same entry with reason R-DEAD -> verifies: {r['forged_reason_verifies']}\", \"זיוף נכשל\", bad=not r[\"forged_reason_verifies\"])]\n        ck += [[\"inclusion_ok\", r[\"verified\"]], [\"forged_fails\", not r[\"forged_reason_verifies\"]]]\n    elif sc == \"rewrite\":\n        r = lab_rewrite()\n        ev += [_ev(\"L\", \"M\", \"old head\", f\"monitor keeps yesterday's head: size={r['old_size']:,} root={r['old_root']}\", \"ראש של אתמול\"),\n               _ev(\"O\", \"L\", \"growth\", f\"log grows to {r['new_size']:,}; honest consistency proof ({r['proof_len']} hashes) -> {r['honest_consistent']}\", \"גדל\", ok=r[\"honest_consistent\"]),\n               _ev(\"L\", \"L\", \"rewrite\", f\"operator rewrites entry {r['tampered_entry']:,} and rebuilds: new root {r['tampered_root']}\", \"שכתוב\", bad=True),\n               _ev(\"L\", \"M\", \"check\", f\"consistency proof against yesterday's head fails -> caught: {r['rewrite_caught']}\", \"נתפס\", ok=r[\"rewrite_caught\"])]\n        ck += [[\"rewrite_caught\", r[\"rewrite_caught\"] and r[\"honest_consistent\"]]]\n    elif sc == \"privacy\":\n        r = lab_privacy()\n        ev += [_ev(\"L\", \"M\", \"public\", \"public fields: \" + \", \".join(r[\"fields_public\"]), \"מה ציבורי\"),\n               _ev(\"M\", \"M\", \"booths\", f\"{r['booths']:,} booths; {r['booths_under_5']:,} have fewer than 5 changes\", f\"{r['booths_under_5']:,} קלפיות\", bad=True),\n               _ev(\"M\", \"M\", \"decision\", \"decision for the spec: public log shows district and week only; booth and date only in the voter's own proof\", \"מחוז ושבוע\", ok=True)]\n        ck += [[\"privacy_measured\", r[\"booths_under_5\"] > r[\"booths\"] * 0.9]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n", "sample-audit": "\"\"\"\nRemoval Sample Audit - proof of concept (pure Python, standard library only).\n\nQuestion: can a random sample of a few hundred deletions per district tell us,\nwith a known margin of error, what share of ALL deletions in that district were\nwrong (the person was still an eligible resident)?\n\nFour labs:\n  1. precision  - sample size vs margin of error (Wilson 95% interval)\n  2. coverage   - repeat the audit 2,000 times: how often does the interval contain the truth?\n  3. stratify   - one \"absent / shifted / other\" bucket hides very different error rates\n  4. ground     - who verifies each sampled case? if the field check is done by the\n                  same machinery that deleted, a share of wrong deletions is \"confirmed\".\n\nHONESTY: the districts, the deletions and the true error rates are SYNTHETIC\n(seeded, deterministic). No real voter data is used. The statistics are real.\nThe same file runs natively and inside the browser (Pyodide).\n\"\"\"\nimport random, math, json\n\nZ = 1.959964\nREASONS = [(\"dead\", 0.03), (\"duplicate\", 0.08), (\"absent_shifted_other\", 0.19)]\n\ndef wilson(k, n, z=Z):\n    if n == 0: return (0.0, 0.0, 1.0)\n    p = k / n; d = 1 + z * z / n\n    c = (p + z * z / (2 * n)) / d\n    h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d\n    return (p, max(0.0, c - h), min(1.0, c + h))\n\ndef make_district(seed, size=120_000, mix=(0.18, 0.12, 0.70), rates=None):\n    \"\"\"A district's deletion list. Each deletion has a reason code and a hidden truth: wrong (1) or right (0).\"\"\"\n    rng = random.Random(seed)\n    rates = rates or {r: e for r, e in REASONS}\n    out = []\n    for i in range(size):\n        u = rng.random()\n        reason = REASONS[0][0] if u < mix[0] else REASONS[1][0] if u < mix[0] + mix[1] else REASONS[2][0]\n        wrong = 1 if rng.random() < rates[reason] else 0\n        out.append((reason, wrong))\n    return out\n\ndef true_rate(d, reason=None):\n    xs = [w for r, w in d if reason is None or r == reason]\n    return sum(xs) / len(xs)\n\ndef audit(d, n, rng, confirm_bias=0.0):\n    \"\"\"Sample n deletions, verify each. confirm_bias = probability that a WRONG deletion is\n    wrongly 'confirmed' by a field check run by the same machinery that deleted.\"\"\"\n    s = rng.sample(d, n); k = 0\n    for reason, wrong in s:\n        if wrong and rng.random() >= confirm_bias: k += 1\n    return wilson(k, n)\n\ndef lab_precision(seed=7):\n    d = make_district(seed); t = true_rate(d); rng = random.Random(seed + 1)\n    rows = []\n    for n in (100, 300, 600, 1000, 1500, 3000):\n        p, lo, hi = audit(d, n, rng)\n        rows.append({\"n\": n, \"est\": round(p * 100, 2), \"lo\": round(lo * 100, 2), \"hi\": round(hi * 100, 2), \"moe\": round((hi - lo) * 50, 2)})\n    return {\"truth\": round(t * 100, 2), \"size\": len(d), \"rows\": rows}\n\ndef lab_coverage(seed=11, n=1500, reps=2000):\n    d = make_district(seed); t = true_rate(d); rng = random.Random(seed + 2); hit = 0; widths = []\n    for _ in range(reps):\n        p, lo, hi = audit(d, n, rng)\n        hit += lo <= t <= hi; widths.append(hi - lo)\n    return {\"truth\": round(t * 100, 2), \"n\": n, \"reps\": reps, \"coverage\": round(hit / reps * 100, 1), \"avg_moe\": round(sum(widths) / reps * 50, 2)}\n\ndef lab_stratify(seed=19, n_per=500):\n    d = make_district(seed); rng = random.Random(seed + 3); out = []\n    for reason, _ in REASONS:\n        sub = [x for x in d if x[0] == reason]\n        p, lo, hi = audit(sub, n_per, rng)\n        out.append({\"reason\": reason, \"count\": len(sub), \"truth\": round(true_rate(sub) * 100, 2), \"est\": round(p * 100, 2), \"lo\": round(lo * 100, 2), \"hi\": round(hi * 100, 2)})\n    p, lo, hi = audit(d, 1500, rng)\n    return {\"overall\": {\"truth\": round(true_rate(d) * 100, 2), \"est\": round(p * 100, 2), \"lo\": round(lo * 100, 2), \"hi\": round(hi * 100, 2)}, \"by_reason\": out}\n\ndef lab_ground(seed=23, n=1500, reps=400):\n    d = make_district(seed); t = true_rate(d); out = []\n    for bias in (0.0, 0.1, 0.25, 0.4, 0.6):\n        rng = random.Random(seed + int(bias * 100)); ests = []; cover = 0\n        for _ in range(reps):\n            p, lo, hi = audit(d, n, rng, confirm_bias=bias); ests.append(p); cover += lo <= t <= hi\n        out.append({\"bias\": bias, \"est\": round(sum(ests) / reps * 100, 2), \"coverage\": round(cover / reps * 100, 1)})\n    return {\"truth\": round(t * 100, 2), \"rows\": out}\n\ndef run_all():\n    return {\"precision\": lab_precision(), \"coverage\": lab_coverage(), \"stratify\": lab_stratify(), \"ground\": lab_ground()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: precision | coverage | stratify | ground. Browser-sized repetitions; the full runs are in run_all().\"\"\"\n    ev, ck = [], []\n    if sc == \"precision\":\n        r = lab_precision()\n        ev.append(_ev(\"L\", \"S\", \"district\", f\"synthetic district: {r['size']:,} deletions, hidden truth {r['truth']}% wrong\", \"120,000 מחיקות\"))\n        for row in r[\"rows\"]:\n            ev.append(_ev(\"S\", \"E\", f\"n={row['n']}\", f\"sample {row['n']:>5}: estimate {row['est']}%  [{row['lo']}, {row['hi']}]  margin ±{row['moe']}\", f\"±{row['moe']}\", ok=row[\"n\"] == 1500))\n        m1500 = [x for x in r[\"rows\"] if x[\"n\"] == 1500][0][\"moe\"]\n        ck.append([\"precise\", m1500 < 2.5])\n    elif sc == \"coverage\":\n        r = lab_coverage(reps=300)\n        ev += [_ev(\"L\", \"S\", \"repeat\", f\"300 independent audits of 1,500 cases each (full run: 2,000 audits, 94.8%)\", \"300 ביקורות\"),\n               _ev(\"S\", \"F\", \"check\", \"each case checked in the field by an honest checker\", \"בודק הוגן\"),\n               _ev(\"F\", \"E\", \"interval\", f\"95% interval contained the truth {r['coverage']}% of the time; mean margin ±{r['avg_moe']}\", f\"{r['coverage']}%\", ok=r[\"coverage\"] >= 92)]\n        ck.append([\"honest\", r[\"coverage\"] >= 92])\n    elif sc == \"stratify\":\n        r = lab_stratify()\n        ev.append(_ev(\"L\", \"S\", \"strata\", \"three strata: dead, duplicate, the opaque 'absent, shifted or other' bucket\", \"שלוש שכבות\"))\n        for b in r[\"by_reason\"]:\n            ev.append(_ev(\"S\", \"E\", b[\"reason\"][:9], f\"{b['reason']:>22}: estimate {b['est']}% (truth {b['truth']}%) of {b['count']:,}\", f\"{b['est']}%\", ok=b[\"lo\"] <= b[\"truth\"] <= b[\"hi\"]))\n        big = max(r[\"by_reason\"], key=lambda b: b[\"est\"])\n        ev.append(_ev(\"E\", \"R\", \"where\", f\"most wrong deletions sit in: {big['reason']}\", \"הסל המעורבב\", ok=True))\n        ck.append([\"bucket\", big[\"reason\"] == \"absent_shifted_other\"])\n    elif sc == \"ground\":\n        r = lab_ground(reps=120)\n        ev.append(_ev(\"L\", \"F\", \"checkers\", f\"same district, truth {r['truth']}%; now the field checker belongs to the machinery that deleted\", \"בודק מהמנגנון\"))\n        for row in r[\"rows\"]:\n            ev.append(_ev(\"F\", \"E\", f\"{int(row['bias']*100)}%\", f\"checker 'confirms' {int(row['bias']*100):>2}% of wrong deletions -> estimate {row['est']}%, interval covers truth {row['coverage']}%\", f\"{row['est']}%\", bad=row[\"coverage\"] < 50))\n        ev.append(_ev(\"E\", \"R\", \"warning\", \"the interval stays narrow and convincing; nothing in the number shows the bias\", \"רצועה צרה, במקום הלא נכון\", bad=True))\n        ck.append([\"ground\", r[\"rows\"][2][\"coverage\"] < 20])\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n", "time-lock": "\"\"\"\nExam Paper Time-Lock - proof of concept (pure Python, standard library only).\n\nClaim A (lock): the paper travels encrypted; the key is split 3-of-5 (Shamir) between\nindependent custodians, so no single insider can open it before the exam hour.\nClaim B (trace): every centre's copy carries a hidden watermark, so a leaked page names its centre.\nClaim C (window): the paper stays sealed until minutes before the exam.\n\nFour labs:\n  1. split     - 2 custodians can't open, any 3 can; brute force on the share space is hopeless\n  2. photo     - a leaked PHOTO of a page: the layout watermark is read back, the centre is named\n  3. retype    - the same leak RETYPED, or circulated as an answer key: the watermark is gone\n  4. window    - where the plaintext exists in time: digital delivery vs. printed paper\n\nHONESTY: the exam, centres and leaks are SYNTHETIC. Shamir sharing is real\n(prime field 2^127-1). The cipher is a SHA-256 counter-mode stream built from\nthe standard library for the demo; a real system uses AES-256-GCM. The \"photo\"\nis modelled as a layout-preserving copy (line breaks and spacing kept).\n\"\"\"\nimport hashlib, secrets, random, json\n\nP = (1 << 127) - 1\n\ndef shamir_split(secret, n=5, k=3, rng=secrets):\n    coef = [secret] + [rng.randbelow(P) for _ in range(k - 1)]\n    return [(x, sum(c * pow(x, i, P) for i, c in enumerate(coef)) % P) for x in range(1, n + 1)]\n\ndef shamir_join(shares):\n    s = 0\n    for j, (xj, yj) in enumerate(shares):\n        num = den = 1\n        for m, (xm, _) in enumerate(shares):\n            if m != j: num = num * (-xm) % P; den = den * (xj - xm) % P\n        s = (s + yj * num * pow(den, P - 2, P)) % P\n    return s\n\ndef stream(key: int, n: int) -> bytes:\n    kb = key.to_bytes(16, \"big\"); out = b\"\"; c = 0\n    while len(out) < n: out += hashlib.sha256(kb + c.to_bytes(8, \"big\")).digest(); c += 1\n    return out[:n]\n\ndef encrypt(key, data: bytes): return bytes(a ^ b for a, b in zip(data, stream(key, len(data))))\ndecrypt = encrypt\n\nQUESTIONS = [\n    \"Which organelle produces most of the ATP in a eukaryotic cell?\",\n    \"A body moves in a circle at constant speed. Which quantity is constant?\",\n    \"Which of the following is an example of a covalent network solid?\",\n    \"In Mendel's dihybrid cross, what is the expected phenotype ratio in F2?\",\n    \"Which hormone lowers blood glucose levels?\",\n    \"What is the SI unit of magnetic flux?\",\n    \"Which enzyme unwinds the DNA double helix during replication?\",\n    \"Which gas law relates pressure and volume at constant temperature?\",\n]\n\ndef watermark(text_lines, centre_id, bits=12):\n    \"\"\"Layout watermark: each line ends with one or two spaces before the newline and the\n    paragraph break pattern encodes 12 bits of the centre id. Invisible on paper, visible in a photo's layout.\"\"\"\n    b = [(centre_id >> i) & 1 for i in range(bits)]\n    out = []\n    for i, line in enumerate(text_lines):\n        bit = b[i % bits]\n        out.append(line + (\" \" * (1 + bit)))\n    return \"\\n\".join(out)\n\ndef read_watermark(page: str, bits=12):\n    lines = page.split(\"\\n\"); v = 0; seen = 0\n    for i, line in enumerate(lines[:bits]):\n        tail = len(line) - len(line.rstrip(\" \"))\n        if tail == 0: return None\n        v |= (tail - 1) << i; seen += 1\n    return v if seen >= min(bits, len(lines)) else None\n\ndef lab_split():\n    key = secrets.randbits(126); paper = \"\\n\".join(QUESTIONS).encode()\n    ct = encrypt(key, paper); sh = shamir_split(key)\n    two = shamir_join(sh[:2]); three = shamir_join([sh[0], sh[2], sh[4]]); all5 = shamir_join(sh)\n    return {\"custodians\": 5, \"threshold\": 3, \"two_open\": two == key, \"three_open\": three == key and decrypt(three, ct) == paper,\n            \"five_open\": all5 == key, \"ct_preview\": ct[:12].hex(), \"keyspace_bits\": 126, \"years_bruteforce_at_1e12_per_s\": \"%.1e\" % (2**126 / 1e12 / 3.15e7)}\n\ndef lab_photo(centres=900, seed=4):\n    rng = random.Random(seed); hit = 0; trials = 200\n    for _ in range(trials):\n        c = rng.randrange(1, centres); page = watermark(QUESTIONS * 2, c)\n        if read_watermark(page) == c: hit += 1\n    return {\"centres\": centres, \"trials\": trials, \"traced\": hit, \"rate\": round(hit / trials * 100, 1)}\n\ndef lab_retype(seed=5):\n    rng = random.Random(seed); trials = 200; traced_retype = traced_key = 0\n    for _ in range(trials):\n        c = rng.randrange(1, 900); page = watermark(QUESTIONS * 2, c)\n        retyped = \"\\n\".join(l.rstrip() for l in page.split(\"\\n\"))           # what a phone keyboard produces\n        traced_retype += read_watermark(retyped) == c\n        answer_key = \" \".join(f\"{i+1}-{rng.choice('ABCD')}\" for i in range(len(QUESTIONS) * 2))   # how leaks usually travel\n        traced_key += read_watermark(answer_key) == c\n    return {\"trials\": trials, \"traced_after_retype\": traced_retype, \"traced_answer_key\": traced_key}\n\ndef lab_window():\n    # hours before the exam at which a readable copy of the paper exists, by delivery mode (illustrative timeline)\n    return {\"digital_cbt\": [{\"t\": -0.25, \"where\": \"server unlock at exam centre\", \"readable\": True}],\n            \"paper\": [{\"t\": -72, \"where\": \"printing press\", \"readable\": True}, {\"t\": -36, \"where\": \"trucks and strongrooms\", \"readable\": True},\n                      {\"t\": -2, \"where\": \"centre opens sealed boxes\", \"readable\": True}],\n            \"note\": \"paper must be printed before it is shipped; the lock protects only the file, not the printed copy\"}\n\ndef run_all():\n    return {\"split\": lab_split(), \"photo\": lab_photo(), \"retype\": lab_retype(), \"window\": lab_window()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: split | photo | retype | window.\"\"\"\n    ev, ck = [], []\n    if sc == \"split\":\n        r = lab_split()\n        ev += [_ev(\"V\", \"V\", \"encrypt\", f\"paper encrypted under a random 126-bit key; ciphertext starts {r['ct_preview']}\", \"מוצפן\"),\n               _ev(\"V\", \"K\", \"5 shares\", \"key split into 5 shares, threshold 3 (Shamir over GF(2^127-1))\", \"5 חלקים\"),\n               _ev(\"K\", \"C\", \"2 of 5\", f\"two custodians try to open -> {r['two_open']}\", \"סגור\", ok=not r[\"two_open\"]),\n               _ev(\"K\", \"C\", \"3 of 5\", f\"three custodians at 14:00 -> {r['three_open']}\", \"נפתח\", ok=r[\"three_open\"]),\n               _ev(\"C\", \"C\", \"brute\", f\"guessing the key at 10^12 tries/s: about {r['years_bruteforce_at_1e12_per_s']} years\", \"בלתי אפשרי\", ok=True)]\n        ck.append([\"lock\", (not r[\"two_open\"]) and r[\"three_open\"]])\n    elif sc == \"photo\":\n        r = lab_photo()\n        ev += [_ev(\"V\", \"C\", \"layout\", f\"each of {r['centres']} centres gets its own layout watermark (12 bits)\", \"900 עימודים\"),\n               _ev(\"C\", \"X\", \"photo\", f\"{r['trials']} pages leak as photos\", \"200 דליפות\"),\n               _ev(\"X\", \"R\", \"read\", f\"watermark read from the photo: {r['traced']}/{r['trials']} traced ({r['rate']}%)\", f\"{r['rate']}%\", ok=r[\"rate\"] > 95)]\n        ck.append([\"photo\", r[\"rate\"] > 95])\n    elif sc == \"retype\":\n        r = lab_retype()\n        ev += [_ev(\"C\", \"X\", \"retyped\", f\"the same {r['trials']} leaks, retyped on a phone keyboard\", \"טקסט מוקלד\"),\n               _ev(\"X\", \"R\", \"read\", f\"traced after retyping: {r['traced_after_retype']}/{r['trials']}\", \"0\", bad=True),\n               _ev(\"X\", \"R\", \"answers\", f\"traced when the leak is an answer key (1-B, 2-D ...): {r['traced_answer_key']}/{r['trials']}\", \"0\", bad=True)]\n        ck.append([\"retype_measured\", r[\"traced_after_retype\"] == 0])\n    elif sc == \"window\":\n        r = lab_window()\n        for p in r[\"paper\"]:\n            ev.append(_ev(\"V\", \"C\", f\"{int(p['t'])}h\", f\"paper exam: readable copy {abs(p['t']):g} h before ({p['where']}; illustrative timeline)\", f\"{abs(p['t']):g} שעות\", bad=p[\"t\"] <= -36))\n        ev.append(_ev(\"K\", \"C\", \"CBT\", \"computer-based exam: the key opens 15 minutes before, on the centre server; no paper exists\", \"15 דקות\", ok=True))\n        ck.append([\"window_measured\", True])\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n"});
